// Air Register Styles — Style 17 Editorial: LOOK hooks (decoration only).
// OWNER: the style-17 assistant ONLY (this file + demo-style-17-editorial.css). Shared files belong to the lead.
// What it does (read-only, nothing clickable, no API/keys/clicks):
//  1. registers the Bodoni Moda + Instrument Sans fonts from bytes embedded below (FontFace from an ArrayBuffer; the CSP has
//     no font-src, so URL/data: fonts would be blocked). Fonts: Google Fonts, SIL Open Font License 1.1, subset to Latin.
//  2. register page: adds one .st-deco "Feature" column that mirrors the selected cart line (name, qty, price, total) from
//     the existing #cart table, plus static editor's notes with key hints. Removed in off().
// Test: FAKE_PORT=6124 CHROME_PORT=9506 node tests/e2e-styles.js --style 17
// STATUS: BUILT.
'use strict';
(function () {
  const FONTS = [
    ['E17 Bodoni', '', { style: 'normal', weight: '400 900' }],
    ['E17 Bodoni', '', { style: 'italic', weight: '400 900' }],
    ['E17 Sans', '', { style: 'normal', weight: '400 700' }],
  ];
  let faces = null, feat = null, mo = null, timer = 0;
  const b64 = s => { const bin = atob(s), u = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i); return u.buffer; };
  function loadFonts() {
    if (faces || typeof FontFace === 'undefined' || !document.fonts) return;
    faces = [];
    for (const [fam, data, desc] of FONTS) {
      try { const f = new FontFace(fam, b64(data), desc); faces.push(f); document.fonts.add(f); f.load().catch(() => {}); } catch (e) { /* fallback fonts */ }
    }
  }
  const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  const k = s => `<span class="e17-k">${esc(s)}</span>`;
  function readLine() {
    const cart = document.getElementById('cart'); if (!cart) return null;
    const rows = [...cart.querySelectorAll('tr.row')]; if (!rows.length) return { count: 0 };
    const row = cart.querySelector('tr.row.sel') || rows[rows.length - 1];
    const heads = [...document.querySelectorAll('#cartHead th')].map(th => th.textContent.trim().toLowerCase());
    const cells = [...row.children].map(td => td.textContent.trim());
    const col = (re, d) => { const i = heads.findIndex(h => re.test(h)); return i >= 0 ? cells[i] : cells[d]; };
    return { count: rows.length, n: cells[0], code: col(/lookup|code|upc/, 1), name: col(/name|item|desc/, 2), qty: col(/qty|quant/, 3),
      price: col(/price/, 4), total: col(/total/, cells.length - 1), neg: row.classList.contains('neg') };
  }
  function render() {
    timer = 0; if (!feat) return;
    const l = readLine() || { count: 0 };
    const ret = document.documentElement.dataset.mode === 'return';
    const html = l.count ? `
      <div class="e17-ft"><div class="e17-img">${esc(l.n || '1')}<i>Fig. ${esc(l.n || '1')} — ${l.neg ? 'coming back' : 'on the ticket'}</i></div><div>
        <div class="e17-cap e17-red">${ret ? 'Returns desk' : 'Feature'} · Line ${esc(l.n)} of ${l.count}</div>
        <div class="e17-h">${esc(l.name)}</div>
        <p class="e17-dek">Lookup ${esc(l.code || '—')}${l.neg ? ' goes back to the shelf' : ' joins the ticket'} — ${esc(l.qty)} at ${esc(l.price)} apiece.</p>
        <div class="e17-st"><b>−</b><span class="e17-q">${esc(l.qty)}</span><b>+</b><span class="e17-amt">${esc(l.total)}</span><span class="e17-cap">Open item ${k('F7')}</span></div>
      </div></div>`
      : `
      <div class="e17-ft"><div class="e17-img">§<i>Fig. 1 — awaiting the first item</i></div><div>
        <div class="e17-cap e17-red">${ret ? 'Returns desk' : 'Feature'} · Tonight's ticket</div>
        <div class="e17-h">${ret ? 'Scan what comes back' : 'A blank page'}</div>
        <p class="e17-dek">${ret ? 'Return lines are on: every scan goes back to the shelf.' : 'Scan an item, or tap one below — the newest line is featured here.'}</p>
        <div class="e17-st"><span class="e17-cap" style="margin-left:0">Open item ${k('F7')}</span><span class="e17-cap">Find ${k('Ctrl+F')}</span></div>
      </div></div>`;
    feat.querySelector('.e17-main').innerHTML = html;
  }
  const soon = () => { if (!timer) timer = setTimeout(render, 60); };
  function on(ctx) {
    loadFonts();
    if (ctx.page !== 'register') return;
    const wrap = document.querySelector('#app .wrap'); if (!wrap || feat) return;
    feat = document.createElement('div'); feat.className = 'st-deco e17-feat'; feat.setAttribute('aria-hidden', 'true');
    feat.innerHTML = `<div class="e17-main"></div><div class="e17-tail">
      <p class="e17-note">Editor's note: hold tickets park the sale; load them again with ${k('Ctrl+Shift+H')}. Every key from the Index works on every page.</p>
      <div class="e17-let"><div class="e17-cap e17-red">Letters to the register</div><div>“Quantities, please.” — selected line ${k('+')} ${k('−')} ${k('*')} · remove ${k('Del')} · find ${k('Ctrl+Shift+F')} · return ${k('Ctrl+R')}</div></div></div>`;
    wrap.appendChild(feat);
    render();
    const cart = document.getElementById('cart');
    mo = new MutationObserver(soon);
    if (cart) mo.observe(cart, { childList: true, subtree: true, attributes: true, attributeFilter: ['class'], characterData: true });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ['data-mode'] });
  }
  function off() {
    if (mo) { mo.disconnect(); mo = null; }
    if (timer) { clearTimeout(timer); timer = 0; }
    document.querySelectorAll('.e17-feat').forEach(e => e.remove()); feat = null;
    // Cursor fix (LOW 17): take our FontFace objects back out of document.fonts, so switching style leaves nothing behind.
    if (faces && document.fonts) faces.forEach(f => { try { document.fonts.delete(f); } catch (e) { /* already gone */ } });
    faces = null;
  }
  // Mockup button set (STYLES-PLAN 13.3): every other [data-a] button stays in the DOM, hidden by style-17 CSS only,
  // and its shortcut keeps working.
  const BUTTONS = [
    'checkout', 'customer', 'close',                                   // pay bar, F3 line, "In this ticket" heading
    'hold', 'new-sale', 'drawer', 'load-hold', 'aside-put', 'end-of-day', 'clock-out', 'logout', // desk chips
    'open-item', 'return', 'history', 'reprint', 'discount', 'tax-off', 'promo', 'extra-charge', 'gift-card', 'price-check', 'settings', // Index
    '#helpPill', '#hwPill', '#qsIn', '#bulkBtns',                      // Help F1, folio status, catalogue search, "Also in the shop"
    '#sizeL', '#sizeR'                                                 // column-width handles = the column rules (drag still works)
  ];
  if (AirStyle.declare) AirStyle.declare('17', { buttons: BUTTONS });
  AirStyle.register('17', { on, off, buttons: BUTTONS });
})();
